"""OOP for agentic AI: a base Agent class, specialised agents (inheritance),
a polymorphic execute() and a workflow that composes agents. The LLM call is
stubbed so the example runs offline; functional helpers stay outside classes."""
from abc import ABC, abstractmethod

def fake_llm(prompt: str) -> str:              # stand-in for client.chat(...)
    if prompt.startswith("VALIDATE"):
        return "VALID" if "method" in prompt.lower() and len(prompt) > 120 else "INVALID"
    if prompt.startswith("SUMMARISE"):
        body = prompt.split(":", 1)[1].strip()
        return " ".join(body.split()[:25]) + " ..."
    return ""

class Agent(ABC):
    """Abstraction: subclasses hide prompts and tool calls behind execute()."""
    def __init__(self, name, model="demo-model"):
        self.name, self.model, self._memory = name, model, []      # encapsulated state
    def ask_llm(self, prompt):
        reply = fake_llm(prompt); self._memory.append((prompt[:30], reply[:30])); return reply
    @abstractmethod
    def execute(self, paper: str) -> str: ...

class ValidationAgent(Agent):
    def execute(self, paper):
        return self.ask_llm(f"VALIDATE: is this a complete research paper? {paper}")

class SummaryAgent(Agent):
    def execute(self, paper):
        return self.ask_llm(f"SUMMARISE in about 300 words: {paper}")

class ResearchPaperWorkflow:
    """Composition: the workflow has-a validator and has-a summariser."""
    def __init__(self):
        self.agents = [ValidationAgent("validator"), SummaryAgent("summariser")]
    def run(self, paper):
        out = {}
        for agent in self.agents:                 # polymorphism: same call, different behaviour
            out[agent.name] = agent.execute(paper)
            if out[agent.name] == "INVALID": break
        return out

# functional parts: plain functions, no state
def read_paper(text: str) -> str: return " ".join(text.split())
def save_result(result: dict) -> str: return "\n".join(f"{k}: {v}" for k, v in result.items())

paper = read_paper("""Abstract: We study early detection of crop disease from leaf images.
Method: a MobileNet backbone fine-tuned on 8,400 labelled photos with heavy augmentation.
Results: 92.3% accuracy on a held-out farm, versus 85.0% for a colour-histogram baseline.""")
print(save_result(ResearchPaperWorkflow().run(paper)))
print(save_result(ResearchPaperWorkflow().run("A short note without details.")))
print("MRO of SummaryAgent:", [c.__name__ for c in SummaryAgent.__mro__])
try:
    Agent("abstract")
except TypeError as e:
    print("cannot instantiate the abstract base:", str(e).split(" with")[0])
